import{_ as n,l as i,o as a,c as t,v as l,p as c,x as r,d as P,i as d,S as s}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"Blackwell 对推理的含义","description":"","frontmatter":{"title":"Blackwell 对推理的含义","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/blackwell-infer.md","filePath":"llm/blackwell-infer.md","lastUpdated":1789023840000}'),p={name:"llm/blackwell-infer.md"};function B(F,e,E,T,M,h){const o=i("Mermaid");return a(),t("div",null,[e[1]||(e[1]=l('<h1 id="blackwell-对推理的含义" tabindex="-1">Blackwell 对推理的含义 <a class="header-anchor" href="#blackwell-对推理的含义" aria-label="Permalink to &quot;Blackwell 对推理的含义&quot;">​</a></h1><div class="epigraph"><p>第五代 Tensor Core 把 FP4 / FP6 与微缩放推进 MMA，第二代 Transformer Engine 与 72 GPU 的 NVLink 域一起，改变的是推理的工作点，而不只是训练的 MFU。</p><footer>—— NVIDIA Blackwell / GB200 NVL72 产品页与 Transformer Engine 对 NVFP4、MXFP8 的公开说明</footer></div><p><a href="/llm/nvidia-gpu-gen">A100 / H100 / Blackwell</a> 已经按训练与系统形态对齐过三代。推理的屋顶线与训练不同：prefill 仍近计算墙，decode 近 <a href="/llm/decode-memory-wall">显存墙</a>，MoE 还要在专家权重与路由之间置换。Blackwell 对推理有意义的公开变化是三条：更窄的推理精度（NVFP4 / FP6、微缩放）、更大更宽的 HBM3e、以及 GB200 NVL72 把 NVLink 域从 8 拉到 72。厂商写过相对 H100 的「实时万亿参数推理约 30×」一类数字，对象是指定的 1.8T MoE 等配置，本篇不把它写成一般定律。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Hopper 上推理的主流窄精度是 FP8。权重与 KV 相对 FP16 减半流量，decode 仍要每步扫参数与缓存；专家多的模型在 8 卡域内铺不开，decode 的 All-to-All 会漏到节点间网络，逐步延迟被放大。问题不是「再买一张更快的 H100」，而是：能否把权重、激活、KV 再压一档而不把质量打穿；能否把宽专家或宽张量并行留在同一互连域里。</p><p>Blackwell 产品叙事把 FP4 明确偏推理与 test-time scaling。训练仍可走 FP8 第二代引擎，但规划推理集群时，若只按 H100 FP8 的字节/参数去估 HBM，会低估同容量能驻留的并发与上下文，也会低估「必须有 TE / TensorRT-LLM 路径才能吃到 MMA」的软件依赖。</p><h3 id="精度轴-从每张量-fp8-到微缩放-fp4" tabindex="-1">精度轴：从每张量 FP8 到微缩放 FP4 <a class="header-anchor" href="#精度轴-从每张量-fp8-到微缩放-fp4" aria-label="Permalink to &quot;精度轴：从每张量 FP8 到微缩放 FP4&quot;">​</a></h3><p>Hopper TE 的典型 FP8 是每张量一个 FP32 scale。Blackwell 的 NVFP4 把值写成 E2M1 一类四比特格子（TE 文档写幅度大约到 ±6），再配块级微缩放：公开技术说明里常见 16 元素一块、块用 FP8(E4M3) 尺度，另可有张量级 FP32 尺度。MXFP8 是同代的另一种微缩放 FP8。块尺度让局部动态范围分开，避免一张量一个 amax 把多数值挤进少数格子——这对 decode 里逐 token 激活、以及 KV 量化尤其重要。没有块尺度的「裸 INT4 / 裸 FP4」不是同一条硬件路径。</p><p><span class="marginnote">TE 在 Blackwell 上提供 <code>NVFP4BlockScaling</code>、<code>MXFP8BlockScaling</code> 等配方；推理栈（TensorRT-LLM、Model Optimizer）另有权重量化与 KV 量化入口。训练配方与推理校准不要混用。H100 没有原生 NVFP4 MMA。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按工作点选轴，而不是按最高 PFLOPS 选卡。</p><p>Prefill / 大 batch：看 FP4/FP8 Tensor Core 的 \\(P\\)。NVL72 产品表把整柜 NVFP4 与 FP8 峰值分栏列出（稠密、是否含稀疏以脚注为准）。软件必须真正发出第五代 MMA，并带上微缩放元数据；只把权重存成 4 bit、计算升回 FP16，只得到容量。</p><p>Decode / 小 batch：看 HBM 带宽与容量。公开材料把 Blackwell 单卡 HBM3e 写到约 8 TB/s、容量到 192 GB 量级（具体 SKU 以产品页为准）；GB200 NVL72 整柜 GPU 显存与 CPU LPDDR 是相加关系，不是自动统一寻址。KV 与权重能留在近端 HBM，TPOT 才跟带宽走；卸到主机要付 C2C 或更慢的路径。</p><p>宽模型 / 宽 MoE：看 NVLink 域。第五代 NVLink 每 GPU 公开 1.8 TB/s；NVL72 域内集合约 130 TB/s 量级的产品表述。专家并行与张量并行优先画在这 72 卡内，柜外仍走 InfiniBand 或以太网做多副本与存储。这与 <a href="/llm/gb200-nvl72">GB200 NVL72 超节点</a> 的形态一致，本篇只强调它对 <strong>decode 逐步通信</strong> 的含义：域内 All-to-All 的延迟尺度不同于跨机。</p>',14)),(a(),c(s,null,{default:r(()=>[d(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%8E%A8%E7%90%86%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20PF%5B%22Prefill%3A%20%E5%90%83%20FP4%2FFP8%20MMA%22%5D%0A%20%20Q%20--%3E%20DC%5B%22Decode%3A%20%E5%90%83%20HBM%20%E4%B8%8E%20KV%20%E5%AD%97%E8%8A%82%22%5D%0A%20%20PF%20--%3E%20TE%5B%22%E7%AC%AC%E4%BA%8C%E4%BB%A3%20Transformer%20Engine%22%5D%0A%20%20DC%20--%3E%20TE%0A%20%20TE%20--%3E%20DOM%5B%22%E5%9F%9F%E5%86%85%3A%20TP%20%2F%20EP%20%2F%20KV%22%5D%0A%20%20DOM%20--%3E%20NVL%5B%22NVL72%20NVLink%20%E6%88%96%20HGX%208%20%E5%8D%A1%22%5D%0A%20%20DOM%20--%3E%20SO%5B%22%E6%9F%9C%E5%A4%96%3A%20%E5%89%AF%E6%9C%AC%E4%B8%8E%E5%AD%98%E5%82%A8%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[P(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<h3 id="第二代引擎与软件栈" tabindex="-1">第二代引擎与软件栈 <a class="header-anchor" href="#第二代引擎与软件栈" aria-label="Permalink to &quot;第二代引擎与软件栈&quot;">​</a></h3><p>第二代 Transformer Engine 在 Blackwell 上除 FP8 外接管 NVFP4 / MXFP8 的量化、缩放与 GEMM。注意力路径上的加速（产品页对 GB300 一类还有相对上一代注意力的倍数）依赖 cuDNN / 框架是否打开对应核，不是改 GPU 名字即生效。TensorRT-LLM、SGLang、vLLM 要各自声明 Blackwell / FP4 支持版本；同一份 NVFP4 权重在只认 FP8 的运行时里会反量化，回到带宽墙。</p><p>KV 缓存用 FP8 或 FP4 是推理侧最直接的容量杠杆：上下文长度与并发近似与字节成反比。质量损失取决于校准与块尺度，不是硬件保证「FP4 KV 无损」。投机解码、MTP 等 test-time scaling 增加的是 decode 步数与草稿核，Blackwell 的算术密度让草稿与验证核都更便宜，但调度复杂度仍在软件。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>推理为什么对窄精度比训练更敏感：训练可以把误差平均进大 batch 的梯度；decode 每一步的 logits 都直接进采样。微缩放是在「更少比特」和「局部范围」之间折中，使 E2M1 的粗格子仍能表示一层里不同通道的幅度。元数据流量必须算进屋顶线：块尺度太细，scale 本身变成带宽；太粗，退化成每张量 FP8。公开块大小以 TE / 白皮书为准，不要发明另一种块长。</p><p>72 卡域改变的是通信的<strong>几何</strong>，不是取消切分。CUDA 仍见 72 个 device。一层 72 路 TP 把 GEMM 切得很瘦，MMA 形状可能填不满，decode 更糟。合理用法往往是：中等 TP × 宽 EP，或整柜一份 MoE 副本。把 72 卡当成 9 个互不往来的 8 卡副本，等于买了域却按 Hopper HGX 调度——这是推理集群最常见的浪费，而不是芯片的问题。</p><p><span class="marginnote">GB200 Superchip 的 NVLink-C2C 公开双向 900 GB/s，CPU 内存可参与 KV 或权重的第二层。这比 PCIe 卸主机快，仍远慢于 HBM。规划「统一内存」时以编程指南为准，不要假设任意 kernel 都能以 HBM 速率扫 CPU DRAM。</span></p><h3 id="不要把柜级峰值当成单核-decode" tabindex="-1">不要把柜级峰值当成单核 decode <a class="header-anchor" href="#不要把柜级峰值当成单核-decode" aria-label="Permalink to &quot;不要把柜级峰值当成单核 decode&quot;">​</a></h3><p>整柜 NVFP4 PFLOPS 是所有 GPU、理想形状、对应精度（常含稀疏脚注）的加总。单请求 decode 的 \\(M=1\\)，能用到的是一张或数张卡上、受 HBM 约束的一小段。并发上去之后，prefill 批处理与 decode 批处理才开始靠近表头。PD 分离、连续批、分页 KV 仍然决定你能不能把 Blackwell 的 \\(P\\) 与 \\(B\\) 同时用上。换代而不改调度，只会得到「卡更贵、SLO 依旧」。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用 A100 的 INT8 或 H100 的 FP8 校准表直接当 NVFP4 质量验收。不要在非 Blackwell 的卡上用软件模拟 FP4 报吞吐。不要把 30×、10× MoE 等营销倍数写进容量规划的分母；规划用字节、带宽、域大小、以及自己的 TTFT/TPOT。不要混用 HGX Blackwell 8 卡域与 NVL72 的并行度配置。GB300 / Blackwell Ultra 是同代内的容量与注意力步进，域规模仍是 72，见 NVL72 专文。</p><p>功耗与液冷是推理机房的硬边界：NVL72 是液冷超节点，不是把八张风冷卡换 SKU。MIG 等多实例能力以该代用户指南为准，不要抄 H100 的 7×10GB 切片表。</p><p><span class="marginnote">出处：NVIDIA GB200 NVL72 产品页（72 GPU / 36 Grace、NVLink 域、精度分栏）；开发者博客 <em>GB200 NVL72 Delivers Trillion-Parameter LLM Training and Real-Time Inference</em>；Transformer Engine 文档中 NVFP4 / MXFP8 配方。未出现在这些材料里的背板单通道速率不写。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Blackwell 推理的三条公开杠杆是 NVFP4/微缩放、\\(B\\) 与 HBM 容量、以及最大 72 的 NVLink 域。</li><li>第二代 Transformer Engine 是吃到 FP4 MMA 的软件合同；无路径则只剩存储压缩。</li><li>Decode 仍受显存墙约束；整柜 PFLOPS 不等于单请求 TPOT。</li><li>宽 EP / 宽 TP 应留在域内；按 8 卡副本调度会浪费 Superchip 互连。</li><li>厂商加速比绑定指定模型与精度，不能当普遍定律。</li><li>出处：NVIDIA Blackwell / GB200 公开材料与 TE 文档；代际对照见 <a href="/llm/nvidia-gpu-gen">A100 / H100 / Blackwell</a>。</li></ul>',15))])}const k=n(p,[["render",B]]);export{m as __pageData,k as default};
